function drawPiece(i,events){const cells=cellsOf(i);if(!cells.length)return'';const[x,y]=center(cells),chosen=state.items.find(p=>p.id===selected),match=chosen&&chosen.id!==i.id&&chosen.chain===i.chain&&chosen.level===i.level,step=suggestion(),suggested=!chosen&&(hintVisible||!taskDone(state,'roof'))&&step.type==='merge'&&[step.a,step.b].includes(i.id),event=events.find(e=>e.itemId===i.id||e.itemIds?.includes(i.id)),s=layout.size,w=cells.length===3?88:Math.min(66,s*1.8),label=cells.length===3?`${nameOf(i)} · 3格`:nameOf(i),ready=canBuild(state,i);return`<g class="piece${cells.length===3?' multi':''}${selected===i.id?' selected':''}${match?' match':''}${suggested?' suggested':''}${event?.type==='growth'?' grow':event?' pop':''}${event&&i.level>=4?' milestone':''}${ready?' deliverable':''}" data-piece="${i.id}" data-cx="${x}" data-cy="${y}" role="button" tabindex="0" aria-label="${nameOf(i)}，L${i.level}，占${cells.length}格，可移动"><path class="piece-side" d="${outline(cells)}" transform="translate(0,5)"/><path class="piece-top" d="${outline(cells)}"/>${cells.length===3?cells.map(c=>`<circle cx="${point(c)[0]}" cy="${point(c)[1]}" r="2.7" fill="#ba944a55"/>`).join(''):''}${sprite(materialArt(i),cells,'piece-art',materialScale(i.level))}<g pointer-events="none"><rect class="piece-label-bg" x="${x-w/2}" y="${y+s*.36}" width="${w}" height="17" rx="7"/><text class="piece-label" x="${x}" y="${y+s*.36+11}" text-anchor="middle">${label}</text><circle cx="${x-s*.59}" cy="${y-s*.5}" r="9.5" fill="#fff9e9" stroke="#c2a263"/><text x="${x-s*.59}" y="${y-s*.5+3}" text-anchor="middle" font-size="8" fill="#8b713f">L${i.level}</text>${ready?`<circle cx="${x+s*.57}" cy="${y-s*.48}" r="10" fill="#5c9e76" stroke="#f4f6dc" stroke-width="1.5"/><path d="m${x+s*.57-4},${y-s*.48} 3 3 5-6" stroke="#fffde8" stroke-width="2" fill="none"/>`:''}</g></g>`;}
