  $('#space-count').textContent=view==='world'?`共用空地 ${freeCount(state)} / ${workCells(state).length}`:`${activeView==='camp'?'营地':'河湾'}空地 ${freeCount(state,activeView)} / ${workCells(state,activeView).length}`;$('#map-status').textContent=previewId?'修复落点 · 新空地已标出':view==='world'?'点区域回近景':practice?state.items.some(isTrial)?'点蓝色组件，可取回':state.items.some(i=>i.chain==='water'&&i.level>=5)?'选中组件，试装后可取回':'按住 L2，连续拖向同级素材':selected?'拖动摆放 · 同级合成':'草地可摆放 · 水面与建筑不可放';$('#world').innerHTML=icon('world')+(view==='world'?'回到修复':'故乡全景');$('#undo').disabled=!history.length||busy;$('#sound').innerHTML=icon(sound?'sound':'mute');$('#sound').setAttribute('aria-label',sound?'关闭音效':'开启音效');
  const item=state.items.find(i=>i.id===selected),selectedReady=canBuild(state,item);let label,detail,cls='';
  if(lastRepair){label=regionComplete(state)?'看看这一站的收获':'继续下一处修复';detail='修好的地方和新空地都会留在地图上';cls='confirm';}
