function primaryAction(){if(busy||drag)return;if(lastRepair){lastRepair=null;render();if(regionComplete(state))showSettlement();return;}if(view==='world'){camera(state.region);return;}if(previewId){confirmBuild();return;}const i=state.items.find(p=>p.id===selected);if(isTrial(i)){execute({type:'RETRIEVE',id:i.id});return;}if(canBuild(state,i)){beginBuild(i.id);return;}const h=suggestion();if(h.type==='win')openMatch();else if(h.type==='open'||h.type==='draw')collectSupply();else if(h.type==='retrieve')execute({type:'RETRIEVE',id:h.id});else if(h.type==='focus')focusGoal(h.task.id);else if(h.type==='merge')showMergeHint(h);else if(h.type==='build')beginBuild(h.id);else if(h.type==='finish')showSettlement();else if(h.type==='done')camera('world');else taskClick();}
function tapPiece(id){if(busy||drag)return;lastRepair=null;const i=state.items.find(p=>p.id===id),other=state.items.find(p=>p.id===selected);if(!i)return;if(other&&other.id!==i.id&&other.chain===i.chain&&other.level===i.level){execute({type:'MERGE',a:other.id,b:i.id});return;}selected=selected===id?null:id;previewId=null;render();}
function taskClick(id){if(typeof id==='string'&&id!==currentTask(state)?.id)focusGoal(id);if(busy||drag)return;if(lastRepair){lastRepair=null;render();return;}const task=currentTask(state);if(!task){showSettlement();return;}const i=taskItem(state);if(i){beginBuild(i.id);return;}view=state.region;pan=[0,0];const h=suggestion();selected=h.a||null;hintVisible=true;render();if(selected)focusItem(state.items.find(i=>i.id===selected));notice(task.title,task.problem);}
function showMergeHint(h=suggestion()){if(h.type!=='merge')return;hintVisible=true;selected=h.a;render();focusItem(state.items.find(i=>i.id===h.a));notice('拖到发光的另一件上','也可以依次点选两件相同素材。落点决定新素材在哪里。');}
function focusGoal(id){if(busy||drag||!availableTasks(state).some(t=>t.id===id))return;execute({type:'FOCUS',id});view=state.region;pan=[0,0];render();const t=currentTask(state);revealCells(siteCells(t.site));notice('先做：'+t.short,t.reward+' · 可随时换目标');}
function collectSupply(single=false){if(busy||drag)return;if(state.pending.length){execute({type:single?'DRAW':'COLLECT',view});return;}const choices=supplyChoices(state);if(progress(state).opened>=progress(state).wins){openMatch();return;}if(choices.length===1){execute({type:single?'OPEN':'COLLECT',chain:choices[0].chain,view});return;}
  openDialog(heading('这一箱，先带回什么？','选好材料，一键上场')+'<p>选择后一次放下这箱材料。空地不够的会留在箱中，也可以先开箱留着。</p><div class="supply-options">'+choices.map(c=>{const task=availableTasks(state).find(t=>t.chain===c.chain),m=mergeMilestone(state,task);const reachable=m.afterBoxLevel>=task.level?`可备齐${nameOf(task)} · 能修复`:`可备齐${nameOf({chain:c.chain,level:m.afterBoxLevel})} L${m.afterBoxLevel}`;return`<button data-action="choose-supply" data-chain="${c.chain}" data-single="${single}">${materialIcon({chain:c.chain,level:m.afterBoxLevel})}<span><strong>${CHAIN_LABELS[c.chain]}${currentTask(state)?.chain===c.chain?' · 当前目标':''}</strong><em>${reachable}</em><small>本箱 ${c.pieces.length} 件 · 原料齐后需手动合成</small></span><b>›</b></button>`;}).join('')+'</div><button class="text-button" data-action="close">先留着，回地图看看</button>');
}

function hit(event){const node=document.elementFromPoint(event.clientX,event.clientY);if(!node||!map.contains(node))return null;const p=node.closest('[data-piece]'),task=node.closest('[data-task]'),region=node.closest('[data-region]'),scene=node.closest('[data-scenery]'),frontier=node.closest('[data-frontier]'),trial=node.closest('[data-trial-socket]'),installed=node.closest('[data-installed]');return installed?{installed:installed.dataset.installed}:trial?{trial:trial.dataset.trialSocket}:p?{piece:p.dataset.piece}:task?{task:task.dataset.task}:region?{region:region.dataset.region}:frontier?{frontier:frontier.dataset.frontier}:scene?{scene:scene.dataset.scenery}:{cell:cellAt(localPoint(event))};}
function dropPreview(plan,item,merging=false){const layer=$('#preview-layer');if(!layer)return;let html=plan.cells?.length?`<path class="drop-preview${plan.ok?'':' invalid'}" d="${outline(plan.cells)}"/>`:'';for(const f of plan.discoveries||[])html+=`<path class="frontier-preview" d="${outline([f.cell])}"/>`;if(plan.ok)html+=sprite(materialArt(item),plan.cells,'drop-art',materialScale(item.level));for(const move of plan.shifted||[])html+=`<path class="shift-line" d="M${center(cellsOf(state.items.find(i=>i.id===move.id)))} L${center(move.cells)}"/><path class="shift-preview" d="${outline(move.cells)}"/>`;layer.innerHTML=html;$('#drag-note').className='drag-note visible'+(plan.ok?'':' invalid');$('#drag-note').textContent=plan.ok?merging?`松手合成 L${item.level} · ${SIZE[item.level]} 格`:plan.shifted?.length?`${plan.shifted.length} 件素材会整体让位`:'松手放到这里':plan.message;if(plan.ok&&plan.discoveries?.length)$('#drag-note').textContent+=' · 清出 1 格空地，素材保留';}
function paintHeldGesture(){const d=drag,i=state.items.find(p=>p.id===d?.id),layer=$('#preview-layer');if(!d?.moved||!i||!layer)return;map.querySelector(`[data-piece="${i.id}"]`)?.classList.add('dragging');layer.querySelectorAll('.carry-ghost,.chain-trail,.drop-art').forEach(n=>n.remove());if(d.trace?.length>1)layer.insertAdjacentHTML('beforeend',`<polyline class="chain-trail" points="${d.trace.map(point).map(p=>p.join(',')).join(' ')}"/>`);if(d.pointerPoint){const anchor=point([i.q,i.r]),dx=d.pointerPoint[0]-d.offset[0]-anchor[0],dy=d.pointerPoint[1]-d.offset[1]-anchor[1];layer.insertAdjacentHTML('beforeend',`<g class="carry-ghost" transform="translate(${dx},${dy})">${sprite(materialArt(i),cellsOf(i),'carry-art',materialScale(i.level))}</g>`);}if(d.gesture?.steps){$('#drag-note').className='drag-note visible chain-note';$('#drag-note').textContent=`${d.gesture.steps} 连合 · L${i.level} · 继续拖向同级素材，松手保留`;}}

function finishDrag(){const d=drag;drag=null;app.classList.remove('drag-active');$('#drag-note').className='drag-note';$('#drag-note').textContent='';return d;}
function cancelHeldGesture(){const d=finishDrag();if(!d)return;if(d.gesture)state=cancelMergeGesture(d.gesture);selected=d.previousSelected;previewId=null;render();}
function commitHeldGesture(d){let action=null;if(d.drop?.type==='merge'){const r=extendMergeGesture(d.gesture,d.drop.other);if(r.ok)d.gesture=r.gesture;}if(d.drop?.type==='move')action={type:'MOVE',q:d.drop.q,r:d.drop.r};else if(d.drop?.type==='try')action={type:'TRY',socket:d.drop.socket};const result=finishMergeGesture(d.gesture,action);if(!result.ok&&!d.gesture.steps){state=d.gesture.base;selected=d.previousSelected;render();notice('放回原位',result.message,true);return;}state=result.state;selected=result.selected;history.push(structuredClone(d.gesture.base));history=history.filter(old=>sameMatchCheckpoint(state,old)).slice(-35);lastRepair=null;previewId=null;hintVisible=false;persist();render(result.events);focusItem(state.items.find(i=>i.id===selected));if(!result.ok){notice('合成已保留，组件留在最后的落点',result.message,true);}else if(d.drop?.type==='build'){if(d.drop.taskId!==currentTask(state)?.id)focusGoal(d.drop.taskId);beginBuild(d.gesture.id);}else if(d.drop?.type==='try')notice('组件正在试装','点蓝色试装标记即可取回，不占工作格。');else if(d.gesture.steps)notice(`完成 ${d.gesture.steps} 次连续合成`,'新组件可以继续摆放；整串合成可一次撤销。');}
map.addEventListener('pointerdown',event=>{if(busy||drag||event.isPrimary===false||event.button!==0)return;const target=hit(event);if(!target)return;const item=view==='world'?null:state.items.find(i=>i.id===target.piece),p=localPoint(event),anchor=item?point([item.q,item.r]):p;drag={pointer:event.pointerId,target,id:item?.id,start:[event.clientX,event.clientY],offset:[p[0]-anchor[0],p[1]-anchor[1]],pan:[...pan],moved:false,previousSelected:selected,trace:item?[[item.q,item.r]]:[]};map.setPointerCapture(event.pointerId);});
map.addEventListener('pointermove',event=>{if(!drag||drag.pointer!==event.pointerId||busy)return;if(!drag.moved&&Math.hypot(event.clientX-drag.start[0],event.clientY-drag.start[1])<7)return;if(!drag.id){drag.moved=true;pan=[drag.pan[0]+event.clientX-drag.start[0],drag.pan[1]+event.clientY-drag.start[1]];renderMap();return;}let i=state.items.find(p=>p.id===drag.id);if(!i)return;drag.pointerPoint=localPoint(event);if(!drag.moved){drag.moved=true;selected=i.id;previewId=null;lastRepair=null;clearNotice();if(view==='river'){drag.gesture=beginMergeGesture(state,i.id);state=drag.gesture.draft;}app.classList.add('drag-active');render();}const target=hit(event),c=cellAt(localPoint(event)),socket=trialFor(state,i);
  if(socket&&!target?.task&&(target?.trial===socket.id||key(c)===key(socket.cell))){const plan=previewTrial(state,i.id,socket.id);drag.drop={type:'try',socket:socket.id};dropPreview(plan,i);$('#drag-note').textContent='松手试装 · 组件保留，不占工作格';return;}
  const build=previewBuild(state,i.id,target?.task||undefined);if(build.ok&&(target?.task||build.cells.some(x=>key(x)===key(c)))){drag.drop={type:'build',taskId:build.task.id};$('#preview-layer').innerHTML=`<path class="repair-outline" d="${outline(build.cells)}"/>`;$('#drag-note').className='drag-note visible';$('#drag-note').textContent='松手查看修复落点，确认后才消耗';return;}
  if(target?.piece&&target.piece!==i.id){const b=state.items.find(x=>x.id===target.piece);if(b?.chain===i.chain&&b.level===i.level&&i.level<CAPS[i.chain]){const plan=previewMerge(state,i.id,b.id);if(drag.gesture&&plan.ok){const [px,py]=localPoint(event),[bx,by]=center(cellsOf(b));if(Math.hypot(px-bx,py-by)<layout.size*.78){const r=extendMergeGesture(drag.gesture,b.id);if(r.ok){drag.gesture=r.gesture;state=r.gesture.draft;drag.id=r.gesture.id;selected=drag.id;i=state.items.find(p=>p.id===drag.id);drag.trace.push([i.q,i.r]);const anchor=point([i.q,i.r]);drag.offset=[px-anchor[0],py-anchor[1]];drag.drop={type:'hold'};render(r.gesture.events.slice(-1));chime(i.level===7?'growth':'merge',r.gesture.steps);return;}}}drag.drop={type:'merge',other:b.id};dropPreview(plan,plan.ok?{chain:i.chain,level:plan.level}:i,true);paintHeldGesture();return;}}
  const p=localPoint(event),cell=cellAt([p[0]-drag.offset[0],p[1]-drag.offset[1]]);drag.drop={type:'move',q:cell[0],r:cell[1]};dropPreview(previewMove(state,i.id,cell[0],cell[1]),i);paintHeldGesture();
});
map.addEventListener('pointerup',event=>{if(!drag||drag.pointer!==event.pointerId)return;const d=finishDrag();if(map.hasPointerCapture(event.pointerId))map.releasePointerCapture(event.pointerId);if(d.moved){if(!d.id)return;const rect=map.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom){if(d.gesture)state=cancelMergeGesture(d.gesture);selected=d.previousSelected;render();return;}if(d.gesture){commitHeldGesture(d);return;}if(d.drop?.type==='try')execute({type:'TRY',id:d.id,socket:d.drop.socket});else if(d.drop?.type==='build'){if(d.drop.taskId!==currentTask(state)?.id)focusGoal(d.drop.taskId);beginBuild(d.id);}else if(d.drop?.type==='merge'){if(!execute({type:'MERGE',a:d.id,b:d.drop.other}))render();}else if(d.drop?.type==='move'){if(!execute({type:'MOVE',id:d.id,q:d.drop.q,r:d.drop.r}))render();}else render();return;}const h=d.target;if(h.installed){selected=selected===h.installed?null:h.installed;previewId=null;render();}else if(h.trial&&selected)execute({type:'TRY',id:selected,socket:h.trial});else if(h.region)camera(h.region);else if(view==='world'){const c=cellAt(localPoint(event));camera(distance(c,OFFSETS.camp)<distance(c,OFFSETS.river)?'camp':state.regions.river?'river':'camp');}else if(h.piece)tapPiece(h.piece);else if(h.task)taskClick(h.task);else if(h.frontier)execute({type:'EXPLORE',id:h.frontier});else if(h.scene){const t=availableTasks(state).find(t=>t.site===h.scene);if(t)taskClick(t.id);else notice('这处景观留在这里','草地、道路可以摆放素材，拖动时会显示可用格。');}else if(h.cell&&isTrial(state.items.find(i=>i.id===selected))){selected=null;render();}else if(h.cell&&selected)execute({type:'MOVE',id:selected,q:h.cell[0],r:h.cell[1]});});
map.addEventListener('pointercancel',cancelHeldGesture);map.addEventListener('lostpointercapture',()=>{if(drag)cancelHeldGesture();});window.addEventListener('blur',()=>{if(drag)cancelHeldGesture();});window.addEventListener('resize',()=>{if(drag)cancelHeldGesture();});
map.addEventListener('keydown',event=>{if(!['Enter',' '].includes(event.key)||busy||drag)return;const t=event.target.closest('[data-piece],[data-task],[data-region],[data-cell],[data-frontier],[data-installed],[data-trial-socket]');if(!t)return;event.preventDefault();if(t.dataset.installed){selected=selected===t.dataset.installed?null:t.dataset.installed;render();}else if(t.dataset.trialSocket&&selected)execute({type:'TRY',id:selected,socket:t.dataset.trialSocket});else if(t.dataset.piece)tapPiece(t.dataset.piece);else if(t.dataset.task)taskClick(t.dataset.task);else if(t.dataset.frontier)execute({type:'EXPLORE',id:t.dataset.frontier});else if(t.dataset.region)camera(t.dataset.region);else if(t.dataset.cell&&selected){const[q,r]=t.dataset.cell.split(',').map(Number);execute({type:'MOVE',id:selected,q,r});}});
const heading=(eyebrow,title)=>`<div class="dialog-heading"><div><small>${eyebrow}</small><h2>${title}</h2></div><button class="dialog-close" data-action="close" aria-label="关闭">${icon('close')}</button></div>`;
function openDialog(html){$('#dialog-body').innerHTML=html;if(!dialog.open)dialog.showModal();}
function closeDialog(){if(dialog.open)dialog.close();}
function showSettlement(){if(!regionComplete(state))return;if(progress(state).settled){showJournal();return;}const s=settlement(state);openDialog(heading('这一小片故乡，安顿好了',state.region==='camp'?'沿溪去找水源':'渡船带着归人回来了')+`<p>${state.region==='camp'?'营地的草地和旧路会继续开放。到了河湾，也能把素材搬回来合成。':'溪流已经流回营地，罗恩也回来了。山坡上的灯，留下了下一段故事。'}</p><div class="settlement-list">${s.items.map(i=>`<div>${materialIcon(i)}<span>${i.name} · L${i.level}${i.pending?' · 箱中':''}</span><b>+${i.value}</b></div>`).join('')||'<p>材料刚好用完了。</p>'}</div><p class="muted">保留：${s.items.length} 件素材保留，含地图、暂存和箱中未领取的余料。<br>换补给：按等级价值合计 ${s.value} 点，不影响已建景观和空地。</p><button class="dialog-button" data-action="finish-keep">保留素材，${state.region==='camp'?'沿溪出发':'收好手记'}</button><button class="dialog-button secondary" data-action="finish-recycle">余料换 ${s.value} 点补给，${state.region==='camp'?'再出发':'收好手记'}</button><button class="text-button" data-action="close">再看看这里</button>`);}
function showJournal(){if(busy||drag)return;let html=heading('归乡手记','留一盏等大家回来的灯')+'<p>先安顿母女，再恢复水路和渡口。每一次修复，都会让更多人有路回家、有地方落脚。</p>';for(const key of availableStoryKeys(state)){const scene=STORY_SCENES[key],last=scene.lines.at(-1);html+=`<button class="journal-replay" data-action="story-replay" data-story-key="${key}"><img src="${asset(portraitAsset(last.who))}" alt=""><span><small>${scene.chapter}</small><strong>${scene.title}</strong><p>${last.text}</p></span><b>›</b></button>`;}const t=currentTask(state);if(t)html+=`<div class="journal-current"><small>眼前的事</small><strong>${t.title}</strong><p>${t.problem}</p></div>`;else if(complete(state))html+='<div class="journal-current"><small>下一段旅程 · 尚未开放</small><strong>山坡上的信号灯</strong><p>邻居们沿着水路回来了。接下来，让旧灯塔为更远的归人指路。</p></div>';html+='<button class="dialog-button" data-action="close">回到故乡</button>';openDialog(html);}

function showPractice(){if(busy||drag)return;openDialog(heading('独立示例材料 · 不影响旅程','连合、试装、再取回')+'<div class="help-row"><b>1</b><div><strong>按住一路合</strong><p>从一份 L2 集水碗出发，拖进另一份 L2 的中心，再继续拖向 L3 净水罐和 L4 引水组件。手指不松开，就能连到 L5。</p></div></div><div class="help-row"><b>2</b><div><strong>把组件用起来</strong><p>选中 L5 蓄水组件，点击试装，或拖进蓝色试水位。细水会流进一小段旧渠，原来的工作格空出来。</p></div></div><div class="help-row"><b>3</b><div><strong>取回继续合成</strong><p>点蓝色试装组件，再点取回。组件等级不变，水流试装效果撤回。继续赢得物资箱，就能合出下一份同级组件。</p></div></div><button class="dialog-button" data-action="close">开始动手</button><button class="text-button" data-action="reset">重新摆好示例材料</button>');}
function showHelp(){if(busy||drag)return;openDialog(heading('风暴之后','一点点修好我们的家')+`<div class="help-row"><b>1</b><div><strong>三消带回材料</strong><p>进入三消关卡，在限定步数内收集目标。通关后得到一张物资券。选择需要的材料箱，一键领到空地；放不下的留在箱中。物资箱下面也可以选择单件领取或先开箱留着。失败可免费重试，中途离开会保存棋盘。</p></div></div><div class="help-row"><b>2</b><div><strong>相同素材合成，再送去修复</strong><p>河湾中按住素材，拖进同级物件中心即可合成；不用松手，还能继续拖向下一件同级素材。松手保留整串，拖出地图或按 Esc 取消。也可以依次点两件合成。L1–L6 占一格，L7 展开成三格。达到试装等级后可放到蓝色试装位，试水、试种或试铺；组件不消耗、不占工作格，点试装位取回后可继续合成。材料够了，主按钮会提示修复。多处可修时，点上方目标卡决定先做哪一处。</p></div></div><div class="help-row"><b>3</b><div><strong>空地是一张共用的地图</strong><p>草地和道路都可放素材，拖动时会显示可用格，水面、遗址、建筑不可放。点选素材再切换区域，可以点那边的空地把它搬过去。拖动空白处可移动视角。边缘标着 L 等级的地块，把达标组件移到旁边或在旁边合成，即可清出空地；组件不会消耗。区域全修好后也能直接清理。</p></div></div><div class="help-row"><b>4</b><div><strong>素材不会悄悄消失</strong><p>修复前显示落点，确认后素材飞过去。拖到被占用的空地，会让挡路素材整体挪开；放不下就回原位。暂存有 6 格，素材可直接合成和交付。多格组件占一个暂存位；取回仍需要连续空地。</p></div></div><button class="dialog-button" data-action="close">继续修复</button>`);}
function showChain(id){const i=state.items.find(x=>x.id===id);if(!i)return;const seen=Math.max(i.level,discoveries[i.chain]||0),goal=currentTask(state);openDialog(heading('素材成长',`${nameOf(i)} · L${i.level}`)+`<p>两件相同素材合成一级。已发现的素材会留在这份手记里，L7 才展开成三格。</p><div class="chain-list">${NAMES[i.chain].slice(1).map((name,j)=>{const level=j+1,isGoal=goal?.chain===i.chain&&goal.level===level,known=level<=seen||isGoal||level===i.level+1;return`<div class="${level===i.level?'current':isGoal?'goal':''}"><span>L${level}</span>${known?`${materialIcon({chain:i.chain,level})}`:'<span class="locked-icon">?</span>'}<b>${known?name:'尚未发现'}</b><small>${isGoal?'本次需要':level===i.level?'当前选中':level<=seen?'已发现':level===i.level+1?'下一次合成':SIZE[level]+'格'}</small></div>`;}).join('')}</div><button class="dialog-button" data-action="close">回到地图</button>`);}
function showSettings(){if(busy||drag)return;openDialog(heading('风暴之后 · 试玩版','旅途设置')+`<button class="setting" data-action="help"><span>怎么玩<small>合成、修复与共用空地</small></span>${icon('hint')}</button><button class="setting" data-action="journal"><span>归乡手记<small>回看已经发生的故事</small></span>${icon('book')}</button><button class="setting" data-action="sound"><span>轻柔音效</span><b>${sound?'开':'关'}</b></button><button class="setting" data-action="reset"><span>${practice?'重新摆好练习材料':'重新开始本次试玩'}<small>${practice?'只影响这个练习存档':'重置这一版的两站旅程'}</small></span>${icon('undo')}</button><a class="setting" href="./?start=river&practice=1"><span>练习连续合成与试装<small>独立示例材料，不影响当前旅程</small></span>${icon('arrow')}</a><a class="setting" href="./first-stop.html"><span>回看上一版<small>一局营地、三局河湾 · 旧进度保留</small></span>${icon('arrow')}</a><p class="muted">本版是独立存档。营地 8 次胜利、4 次修复；河湾 12 次胜利、6 次修复。三消为 20 个可玩关卡，通关后领取素材箱。</p>`);}
document.addEventListener('click',event=>{const b=event.target.closest('[data-action]');if(!b||busy||drag)return;const action=b.dataset.action,id=b.dataset.id;if(action==='try'){const socket=trialFor(state,state.items.find(i=>i.id===id));if(socket)execute({type:'TRY',id,socket:socket.id});}else if(action==='retrieve')execute({type:'RETRIEVE',id});else if(action==='focus-goal')focusGoal(id);else if(action==='choose-supply'){closeDialog();execute({type:b.dataset.single==='true'?'OPEN':'COLLECT',chain:b.dataset.chain,view});}else if(action==='story-replay')playStory(b.dataset.storyKey,true);else if(action==='select')tapPiece(id);else if(action==='store')execute({type:'STORE',id});else if(action==='restore')execute({type:'RESTORE',id,view:view==='world'?state.region:view});else if(action==='rotate')execute({type:'ROTATE',id});else if(action==='chain')showChain(id);else if(action==='focus-piece')focusItem(state.items.find(i=>i.id===id));else if(action==='close')closeDialog();else if(action==='camera')camera(b.dataset.region);else if(action==='help')showHelp();else if(action==='journal')showJournal();else if(action==='sound'){sound=!sound;persist();render();showSettings();chime('merge');}else if(action==='finish-keep'||action==='finish-recycle')execute({type:'FINISH',recycle:action==='finish-recycle'});else if(action==='reset'&&practice)openDialog(heading('重新练习','重新摆好示例材料？')+'<p>只重置这个练习存档。正常旅程和未完成的三消都不受影响。</p><button class="dialog-button" data-action="reset-confirm">重新摆好示例材料</button><button class="dialog-button secondary" data-action="close">继续现在的练习</button>');else if(action==='reset')openDialog(heading('重新体验','从风暴后的第一晚开始？')+'<p>这一版的营地和河湾进度会重置。上一版的存档仍然保留。</p><button class="dialog-button" data-action="reset-confirm">重新开始本次试玩</button><button class="dialog-button secondary" data-action="close">继续现在的旅程</button>');else if(action==='reset-confirm'){state=practice?demoRiverHandsOn():demo?demoRiver():freshGame();storyData=restoreStory(state,null,practice);history=[];discoveries={};matchSession=null;matchOpen=false;matchUI.hide();lastRepair=null;hintVisible=false;selected=null;previewId=null;view=demo?'river':'camp';pan=[0,0];persist();closeDialog();render();if(storyData.cursor)playStory(storyData.cursor.key);}});
$('#supply-crate').addEventListener('click',()=>collectSupply(false));$('#supply-single').addEventListener('click',()=>collectSupply(true));
$('#primary').addEventListener('click',primaryAction);$('#cancel').addEventListener('click',()=>{if(!busy){previewId=null;render();}});$('#extra-win').addEventListener('click',openMatch);$('#task-card').addEventListener('click',taskClick);$('#story-card').addEventListener('click',()=>practice?showPractice():showJournal());$('#settings').innerHTML=icon('settings');$('#settings').addEventListener('click',()=>{if(!busy)showSettings();});$('#sound').addEventListener('click',()=>{if(busy||drag)return;sound=!sound;persist();render();chime('merge');});$('#undo').innerHTML=icon('undo')+'撤销';$('#undo').addEventListener('click',()=>{if(busy||drag||!history.length)return;state=history.pop();lastRepair=null;hintVisible=false;selected=null;previewId=null;view=state.region;pan=[0,0];persist();render();notice('已撤销上一步','素材、地格与修复都已回到上一步。');});$('#hint').innerHTML=icon('hint')+'提示';$('#hint').addEventListener('click',taskClick);$('#world').addEventListener('click',()=>camera(view==='world'?state.region:'world'));$('#recenter').innerHTML=icon('pin');$('#recenter').addEventListener('click',()=>{if(busy||drag)return;pan=[0,0];renderMap();});$('#tray-toggle').addEventListener('click',()=>{if(busy||drag)return;trayOpen=!trayOpen;render();});
dialog.addEventListener('click',event=>{if(event.target!==dialog)return;const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeDialog();});
window.addEventListener('keydown',event=>{if(event.key==='Escape'&&drag){event.preventDefault();cancelHeldGesture();return;}if(event.key==='Escape'&&!dialog.open&&!busy&&!matchOpen){selected=null;previewId=null;render();}});
new ResizeObserver(()=>{if(!drag&&!busy)renderMap();}).observe(map);
window.__homecoming={getState:()=>structuredClone(state),getLayout:()=>structuredClone(layout),getView:()=>view};
storyUI=createStoryUI({asset,portrait:portraitAsset,onProgress:(cursor,replay)=>{if(!replay){storyData.cursor=cursor;persist();}},onFinish:(key,replay)=>{if(!replay){storyData.seen=[...new Set([...storyData.seen,key])];storyData.cursor=null;persist();}$('#primary').focus({preventScroll:true});}});
app.style.setProperty('--world-background',`url("${asset('craft-world-bg')}")`);
$('#supply-crate img').src=asset('chest');
matchUI=createMatch3UI({root:$('#match-screen'),asset,onChange:session=>{matchSession=session;matchOpen=true;return persist();},onExit:exitMatch,onClaim:awardMatch,onRetry:retryMatch,getSound:()=>sound,onToggleSound:()=>{sound=!sound;persist();}});
if(demo&&!loaded)persist();render();if(matchOpen&&matchSession){app.hidden=true;matchUI.show(matchSession,`为「${currentTask(state)?.short||'故乡修复'}」带回材料`);}

if(!matchOpen&&storyData.cursor)playStory(storyData.cursor.key);
